  if (priority === 2) return "lead";
  if (priority === 1) return "lag";
  return "standby";
})

context.handlebars.registerHelper("state", (run, trip) => {
  if (trip == 1) return "tripped";

  return run == 1 ? "running" : "stopped";
})

context.handlebars.registerHelper("stateClass", (run, trip) => {
  if (trip == 1) return "trip";

  return run == 1 ? "running" : "stopped";
})
