options.helpers:
context.handlebars.registerHelper("priority", priority => {
  if (priority === 2) return "lead";
  if (priority === 1) return "lag";
  return "standby";
})

context.handlebars.registerHelper("state", (run, trip) => {
  if (trip == 1) return "tripped";

  return run == 1 ? "running" : "stopped";
})

context.handlebars.registerHelper("stateClass", (run, trip) => {
  if (trip == 1) return "trip";

  return run == 1 ? "running" : "stopped";
})
context.handlebars.registerHelper('numberFormat', function (value, options) {
  if (value == null) return '--';
  // Helper parameters
  var dl = options.hash['decimalLength'] || 2;
  var ts = options.hash['thousandsSep'] || ',';
  var ds = options.hash['decimalSep'] || '.';

  // Parse to float
  var value = parseFloat(value);

  // The regex
  var re = '\\d(?=(\\d{3})+' + (dl > 0 ? '\\D' : '$') + ')';

  // Formats the number with the decimals
  var num = value.toFixed(Math.max(0, ~~dl));

  // Returns the formatted number
  return (ds ? num.replace('.', ds) : num).replace(new RegExp(re, 'g'), '$&' + ts);
});

context.handlebars.registerHelper('alarmClass', activeAlarms => {
  if (activeAlarms === 0) return 'ok';
  if (activeAlarms === 1) return 'warn';
  return 'bad'
})

context.handlebars.registerHelper('runTime', runtime => {
  const hour = Math.floor(runtime / 60);
  const min = Math.round(runtime % 60);
  return `${hour}h ${min}m`
})

context.handlebars.registerHelper('assignedChr', value => {
  if (!value) return 'not assigned';
  return 'serving ' + value;
})

context.handlebars.registerHelper('autoBadge', (autoMode, controlMode) => {
  if (autoMode === 1 && controlMode === "AUTO") { 
    return `<span class="pump-status-mode auto">AUTO</span>`;
  }

  let result = '';

  if (autoMode === 0) {
    result += `<span class="pump-status-mode manual">MANUAL</span>`
  }
  if (controlMode !== 'AUTO') {
    result += `<span class="pump-status-mode remote">REMOTE</span>`
  }

  return result;
})

// Theme class: 'dark' or 'light' based on the viewer's Grafana theme
context.handlebars.registerHelper('themeClass', () => {
  const theme = context.grafana && context.grafana.theme;
  if (theme) return theme.isDark ? 'dark' : 'light';
  return document.body.classList.contains('theme-light') ? 'light' : 'dark';
});

options.styles:
.pump-status-card {
  width: 100%;
  font-family: var(--font-sans, Inter, Arial, sans-serif);
  color: var(--color-text-primary, #1f2933);
  background: #ffffff;
  border: 1px solid #d0d5dd;
  border-radius: 6px;
  padding: 13px;
}
.pump-status-card.running {
  background: #ecf8e8;
  border-color: #7fb069;
  border-left: 5px solid #548235;
  box-shadow: 0 0 0 1px rgba(84, 130, 53, 0.1);
}
.pump-status-card.stopped {
  background: #fafafa;
  border-color: #e5e7eb;
}
.pump-status-card.trip,
.pump-status-card.error {
  background: #fff5f5;
  border-color: #f2b8b5;
}
.pump-status-card.unavailable {
  background: #f8f9fa;
  border-color: #d0d5dd;
  opacity: 0.78;
}
.pump-status-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 13px;
}
.pump-status-title {
  display: flex;
  align-items: center;
  gap: 9px;
  min-width: 0;
}
.pump-status-name {
  font-size: 17px;
  font-weight: 700;
}
.pump-status-badge {
  border-radius: 999px;
  background: #eaf2ff;
  color: #2f75b5;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.3px;
  padding: 4px 9px;
  text-transform: uppercase;
  white-space: nowrap;
}
.pump-status-badge.standby {
  background: #f2f4f7;
  color: #667085;
}
.pump-status-badge.unassigned {
  background: #fef3c7;
  color: #92400e;
}
.pump-status-mode {
  display: inline-block;
  border-radius: 999px;
  padding: 3px 9px;
  font-size: 13px;
  font-weight: 700;
}
.pump-status-mode.auto {
  background: #dcfce7;
  color: #166534;
}
.pump-status-mode.manual {
  background: #fef3c7;
  color: #92400e;
}
.pump-status-mode.remote {
  background: #ffedd5;
  color: #9a3412;
}
.pump-status-mode.local {
  background: #fee2e2;
  color: #991b1b;
}
.pump-status-state {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 14px;
  font-weight: 700;
  text-transform: uppercase;
  white-space: nowrap;
}
.pump-status-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: #548235;
}
.pump-status-card.running .pump-status-state {
  color: #548235;
}
.pump-status-card.stopped .pump-status-dot {
  background: #98a2b3;
}
.pump-status-card.stopped .pump-status-state {
  color: #667085;
}
.pump-status-card.trip .pump-status-dot,
.pump-status-card.error .pump-status-dot {
  background: #c00000;
}
.pump-status-card.trip .pump-status-state,
.pump-status-card.error .pump-status-state {
  color: #c00000;
}
.pump-status-card.unavailable .pump-status-dot {
  background: #667085;
}
.pump-status-card.unavailable .pump-status-state {
  color: #667085;
}
.pump-status-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}
.pump-status-metric {
  min-width: 0;
  border-top: 1px solid rgba(84, 130, 53, 0.16);
  padding-top: 8px;
}
.pump-status-label {
  color: var(--color-text-secondary, #667085);
  font-size: 12px;
  letter-spacing: 0.3px;
  overflow: hidden;
  text-overflow: ellipsis;
  text-transform: uppercase;
  white-space: nowrap;
}
.pump-status-value {
  margin-top: 3px;
  font-size: 18px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.pump-status-unit {
  color: var(--color-text-secondary, #667085);
  font-size: 12px;
  font-weight: 400;
}
.pump-status-ok {
  color: #548235;
}
.pump-status-warn {
  color: #bf8f00;
}
.pump-status-bad {
  color: #c00000;
}
@media (max-width: 360px) {
  .pump-status-grid {
    grid-template-columns: 1fr;
  }
}

/* ---------- Dark theme (only applies when Grafana is in dark mode) ---------- */
