}
*:where(.pump-status-card.dark) .pump-status-badge.unassigned {
  background: rgba(242, 204, 12, 0.16);
  color: #ff9830;
}
*:where(.pump-status-card.dark) .pump-status-mode.auto {
  background: rgba(115, 191, 105, 0.16);
  color: #73bf69;
}
*:where(.pump-status-card.dark) .pump-status-mode.manual {
  background: rgba(242, 204, 12, 0.16);
  color: #ff9830;
}
*:where(.pump-status-card.dark) .pump-status-mode.remote {
  background: rgba(255, 152, 48, 0.16);
  color: #ff9830;
}
*:where(.pump-status-card.dark) .pump-status-mode.local {
  background: rgba(242, 73, 92, 0.16);
  color: #ff7383;
}
.pump-status-card:where(.dark).running .pump-status-state {
  color: #73bf69;
}
.pump-status-card:where(.dark).stopped .pump-status-state {
  color: #b0b0be;
}
.pump-status-card:where(.dark).trip .pump-status-state,
.pump-status-card:where(.dark).error .pump-status-state {
  color: #ff7383;
}
.pump-status-card:where(.dark).unavailable .pump-status-state {
  color: #b0b0be;
}
*:where(.pump-status-card.dark) .pump-status-metric {
  border-top: 1px solid rgba(115, 191, 105, 0.26);
}
*:where(.pump-status-card.dark) .pump-status-label {
  color: var(--color-text-secondary, #b0b0be);
}
*:where(.pump-status-card.dark) .pump-status-unit {
  color: var(--color-text-secondary, #b0b0be);
}
*:where(.pump-status-card.dark) .pump-status-ok {
  color: #73bf69;
}
*:where(.pump-status-card.dark) .pump-status-warn {
  color: #f2cc0c;
}
*:where(.pump-status-card.dark) .pump-status-bad {
  color: #ff7383;
}
